from fastapi.testclient import TestClient

class ArbitraryType:
    def __init__(self, value: str):
        self.value = value
    def __repr__(self):
        return f"ArbitraryType({self.value})"

class Model(BaseModel):
    model_config = ConfigDict(arbitrary_types_allowed=True)
    item: ArbitraryType

app = FastAPI()

@app.post("/test")
async def test_endpoint(item: Model):
    return item

client = TestClient(app)

def test_arbitrary_type():
    # This should fail because we are sending JSON, and Pydantic doesn't know how to 
    # instantiate ArbitraryType from JSON.
    # But the issue might be that FastAPI fails before Pydantic does, or in a way that's not expected.
    try:
        response = client.post("/test", json={"item": {"value": "test"}})
        print(f"Response: {response.status_code}, {response.json()}")
    except Exception as e:
        print(f"Exception: {e}")

if __name__ == "__main__":
    test_arbitrary_type()

